use super::number;

pub fn camelize(input: &str) -> String {
    if input.is_empty() {
        return String::new();
    }

    let mut output = String::with_capacity(input.len());
    let mut uppercase_next = false;

    for ch in input.chars() {
        if ch == '_' {
            uppercase_next = true;
            continue;
        }

        if uppercase_next {
            output.push(ch.to_ascii_uppercase());
            uppercase_next = false;
        } else {
            output.push(ch);
        }
    }

    output
}

pub fn underscore(input: &str) -> String {
    if input.is_empty() {
        return String::new();
    }

    let mut output = String::with_capacity(input.len());

    for (index, ch) in input.chars().enumerate() {
        if ch.is_ascii_uppercase() {
            if index > 0 {
                output.push('_');
            }
            output.push(ch.to_ascii_lowercase());
        } else {
            output.push(ch);
        }
    }

    output
}

pub fn classify(input: &str) -> String {
    let singular = number::singularize(input);
    let camel = camelize(&singular);
    capitalize_first_ascii(&camel)
}

pub fn tableize(input: &str) -> String {
    let underscored = underscore(input);
    number::pluralize(&underscored)
}

pub fn humanize(input: &str) -> String {
    let spaced = input.replace('_', " ");
    capitalize_first_ascii(&spaced)
}

pub fn dasherize(input: &str) -> String {
    input.replace('_', "-")
}

pub fn upcase(input: &str) -> String {
    input.chars().map(|ch| ch.to_ascii_uppercase()).collect()
}

pub fn downcase(input: &str) -> String {
    input.chars().map(|ch| ch.to_ascii_lowercase()).collect()
}

fn capitalize_first_ascii(input: &str) -> String {
    let mut chars = input.chars();
    let Some(first) = chars.next() else {
        return String::new();
    };

    let mut output = String::with_capacity(input.len());
    output.push(first.to_ascii_uppercase());
    output.extend(chars);
    output
}

